private boolean dispatchObserved(
    UUID id, com.fasterxml.jackson.databind.JsonNode acceptedBinding, Instant now) {
  final JsonNode binding;
  try {
    binding = transactions.execute(status -> observed.refreshRetry(acceptedBinding, instanceId));
  } catch (RuntimeException refusal) {
    close(id, observedRefusalCode(refusal), now);
    return false;
  }
  UUID attempt = UUID.fromString(binding.path("attemptId").asText());
  boolean sendCommitted = false;
  try {
    UITestRevision revision =
        revisions.findById(UUID.fromString(binding.path("revisionId").asText())).orElseThrow();
    ReferenceDeclarations declared =
        ExecutionReferences.declared(objectMapper, revision.getReferences());
    try (var resolvedJob = observed.job(binding, plainVariablesOf(id, declared), secretId -> {
      if (secretAudit == null) throw new IllegalStateException("Missing secret read-entry audit");
      transactions.executeWithoutResult(status -> secretAudit.replayReadEntry(binding, instanceId, secretId));
    })) {
      RunJob job = resolvedJob.runJob();
      Integer began =
          transactions.execute(
              status -> {
                observed.check(binding);
                int dispatchRows = statements.beginObservedDispatch(id, instanceId, attempt);
                if (dispatchRows == 1 && secretAudit != null)
                  secretAudit.replayRelease(
                      binding,
                      declared.secrets(),
                      resolvedJob.resolved().secretVersions(),
                      com.citi.put.checks.studio.secrets.SecretUseAuditRecorder.ResolutionOutcome
                          .RESOLVED);
                return dispatchRows;
              });
      if (began == null || began != 1) {
        return false;
      }
      sendCommitted = true;
      DispatchOutcome outcome = runnerClient.send(job);
      applyOutcome(
          id,
          attempt,
          outcome,
          instant(statements.find(id).orElseThrow().get("pending_deadline_at")),
          now);
      return true;
    }
  } catch (VaultProviderUnavailableException failure) {
    settleObservedFailure(binding, failure, null, now);
    return false;
  } catch (StudioReferenceResolver.SecretUseRevokedException failure) {
    settleObservedFailure(binding, failure, ExecutionErrorCode.AUTHORIZATION_REVOKED, now);
    return false;
  } catch (com.citi.put.checks.studio.secrets.VaultStudioReferenceResolver.SecretTooLongException failure) {
    settleObservedFailure(binding, failure, ExecutionErrorCode.SECRET_TOO_LONG, now);
    return false;
  } catch (StudioReferenceResolver.ReferenceUnavailableException failure) {
    settleObservedFailure(binding, failure, ExecutionErrorCode.REFERENCE_UNAVAILABLE, now);
    return false;
  } catch (RuntimeException refusal) {
    if (sendCommitted) return true;
    settleObservedFailure(binding, refusal, observedRefusalCode(refusal), now);
    return false;
  }
}

/** Genuine pre-send decision and its owner transition commit or roll back as one unit. */
void settleObservedFailure(JsonNode binding, RuntimeException failure, String failureCode, Instant now) {
  UUID id=UUID.fromString(binding.path("executionId").asText());
  UUID attempt=UUID.fromString(binding.path("attemptId").asText());
  transactions.executeWithoutResult(status -> {
    if (!statements.lockObservedResolutionOwner(id, instanceId, attempt)) return;
    var owner=statements.find(id).orElseThrow();
    String code=owner.get("cancel_requested_at")!=null ? ExecutionErrorCode.CANCELLED
        : owner.get("revoked_at")!=null ? ExecutionErrorCode.AUTHORIZATION_REVOKED : failureCode;
    auditObservedFailure(binding, failure);
    if (java.util.Arrays.stream(failure.getSuppressed()).anyMatch(StudioReferenceResolver.ResolutionFacts.class::isInstance)) {
      if (secretAudit == null) throw new IllegalStateException("Missing secret no-send audit");
      secretAudit.replayNoSendDecision(binding, instanceId, StudioReferenceResolver.positivelyNotEntered(failure),
          code == null ? com.citi.put.checks.studio.secrets.SecretUseAuditRecorder.NoSendDisposition.REQUEUED
              : com.citi.put.checks.studio.secrets.SecretUseAuditRecorder.NoSendDisposition.CLOSED);
    }
    int applied=code==null ? statements.releaseObservedOutageClaim(id, instanceId, attempt)
        : statements.closeWithError(id, code, now);
    if (applied!=1) throw new IllegalStateException("Observed failure decision lost its owner transition");
  });
}

private static String observedRefusalCode(RuntimeException refusal) {
  if (!(refusal instanceof com.citi.put.checks.studio.guided.session.GuidedSessionException))
    return ExecutionErrorCode.DISPATCH_FAILED;
  if ("CANCELLED".equals(refusal.getMessage())) return ExecutionErrorCode.CANCELLED;
  return java.util.Set.of("AUTHORIZATION_EXPIRED", "FORBIDDEN_SCOPE", "SECRET_USE_REVOKED", "SECRET_USE_NOT_AUTHORIZED").contains(refusal.getMessage())
      ? ExecutionErrorCode.AUTHORIZATION_REVOKED : ExecutionErrorCode.DISPATCH_FAILED;
}

private void auditObservedFailure(JsonNode binding, RuntimeException failure) {
  if (!org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive())
    throw new IllegalStateException("Observed failure audit requires its owner transaction");
  if (secretAudit == null) return;
  var decisions = StudioReferenceResolver.decisionFacts(failure);
  if (decisions.isEmpty()) return;
  var declared = ExecutionReferences.declared(objectMapper,
      jdbc.queryForObject("SELECT \"references\"::text FROM ui_test_revisions WHERE id=?", String.class, UUID.fromString(binding.path("revisionId").asText())));
  if (!declared.secrets().containsAll(decisions.keySet()))
    throw new IllegalArgumentException("Undeclared secret decision metadata");
  decisions.forEach((id, decision) -> secretAudit.replayRelease(binding, List.of(id),
        decision.version()==null ? Map.of() : Map.of(id, decision.version()),
        com.citi.put.checks.studio.secrets.SecretUseAuditRecorder.ResolutionOutcome.valueOf(decision.outcome().name())));
  secretAudit.replayNoSend(UUID.fromString(binding.path("executionId").asText()), UUID.fromString(binding.path("attemptId").asText()));
}

/**
 * The three outcomes (AC-15). The ambiguous branch deliberately does nothing at all: no second
 * send, no second attempt, no state change. The row stays {@code DISPATCHING} and recovery owns
 * it.
 */
private void applyOutcome(
    UUID executionId,
    UUID attemptId,
    DispatchOutcome outcome,
    Instant pendingDeadline,
    Instant now) {
  switch (outcome.kind()) {
    case ACCEPTED -> {
      // Nothing to write: the admission CAS is the next durable step and the runner owns it.
    }
    case DEFINITE_REFUSAL -> {
      boolean withinDeadline = pendingDeadline == null || pendingDeadline.isAfter(now);
      transactions.executeWithoutResult(status -> {
        if (!statements.lockUnadmittedDispatch(executionId, attemptId)) return;
        if (secretAudit != null) secretAudit.replayNoSend(executionId, attemptId);
        var owner=statements.find(executionId).orElseThrow();
        String stopCode=owner.get("cancel_requested_at")!=null ? ExecutionErrorCode.CANCELLED
            : owner.get("revoked_at")!=null ? ExecutionErrorCode.AUTHORIZATION_REVOKED : null;
        if (stopCode!=null) statements.closeWithError(executionId,stopCode,now);
        else if (outcome.retryable() && withinDeadline) {
          statements.returnAfterDefiniteRefusal(executionId, attemptId);
        } else statements.closeWithError(executionId, ExecutionErrorCode.DISPATCH_FAILED, now);
      });
    }
    case AMBIGUOUS ->
        LOGGER.warn(
            "Studio dispatch for execution {} attempt {} is ambiguous ({}); it is NOT resent and "
                + "recovery will resolve it against admission, progress and manifest state",
            executionId,
            attemptId,
            outcome.detail());
    default -> throw new IllegalStateException("Unclassified dispatch outcome");
  }
}

private void close(UUID executionId, String errorCode, Instant now) {
  transactions.execute(status -> statements.closeWithError(executionId, errorCode, now));
}

