  /** Durable possible-read entry, committed by the caller before the existing provider call. */
  @Transactional(propagation = Propagation.MANDATORY)
  public void recordObservedReadEntry(JsonNode binding, String leaseOwner, String secretId) {
    if(secretId==null || !secretId.matches("[A-Za-z0-9_.-]{1,64}")) throw invalid();
    Map<String,Object> metadata=observedMetadata(binding,leaseOwner);
    metadata.put("id",UUID.nameUUIDFromBytes(("read|"+metadata.get("execution_id")+"|"+metadata.get("attempt_id")+"|"+secretId).getBytes(StandardCharsets.UTF_8)));
    metadata.put("secret_id",secretId);metadata.put("occurred_at",Timestamp.from(now()));
    var existing=jdbc.queryForList("SELECT * FROM studio_observed_secret_read_entries WHERE execution_id=? AND attempt_id=? AND secret_id=?",metadata.get("execution_id"),metadata.get("attempt_id"),secretId);
    if(!existing.isEmpty()) {
